// Exact union of the pinned STRONG_RTL expression, not Unicode Bidi_Class R/AL.
// Script properties include digits/marks but exclude some Common/Inherited characters.
// Generated by scanning every Unicode scalar with the original JS expression in
// Chrome 157.0.8103.79 / V8 15.7.112.43 (36 merged ranges, 5,739 matching scalars).
// The source names eight scripts: Adlam, Arabic, Hebrew, Mandaic, Nko, Samaritan,
// Syriac, Thaana; it also includes U+200F, U+061C, and two entire SMP ranges.
// Source SHA-256: ccd48e1d77d9b18499472f22a6d2dd65204eeed4e556a6afdd02a73fd4468a97.
// Engine property data is frozen here; future Unicode versions require regeneration.
const STRONG_RTL_RANGES: &[(u32, u32)] = &[
    (0x591, 0x5C7),
    (0x5D0, 0x5EA),
    (0x5EF, 0x5F4),
    (0x600, 0x604),
    (0x606, 0x60B),
    (0x60D, 0x61A),
    (0x61C, 0x61E),
    (0x620, 0x63F),
    (0x641, 0x64A),
    (0x656, 0x66F),
    (0x671, 0x6DC),
    (0x6DE, 0x70D),
    (0x70F, 0x74A),
    (0x74D, 0x7B1),
    (0x7C0, 0x7FA),
    (0x7FD, 0x82D),
    (0x830, 0x83E),
    (0x840, 0x85B),
    (0x85E, 0x85E),
    (0x860, 0x86A),
    (0x870, 0x891),
    (0x897, 0x8E1),
    (0x8E3, 0x8FF),
    (0x200F, 0x200F),
    (0xFB1D, 0xFB36),
    (0xFB38, 0xFB3C),
    (0xFB3E, 0xFB3E),
    (0xFB40, 0xFB41),
    (0xFB43, 0xFB44),
    (0xFB46, 0xFD3D),
    (0xFD40, 0xFDCF),
    (0xFDF0, 0xFDFF),
    (0xFE70, 0xFE74),
    (0xFE76, 0xFEFC),
    (0x10800, 0x10FFF),
    (0x1E800, 0x1EFFF),
];

/// Whether any character matches upstream's `STRONG_RTL` expression.
///
/// This server-safe presence check does not determine first-strong direction:
/// a preceding Latin letter does not hide a later match, and script-specific
/// combining marks and Arabic digits are not skipped. No DOM or locale is read.
pub(crate) fn has_strong_right_to_left(text: &str) -> bool {
    text.chars().any(|character| {
        let code_point = u32::from(character);
        let index = STRONG_RTL_RANGES.partition_point(|&(start, _)| start <= code_point);
        STRONG_RTL_RANGES[..index]
            .last()
            .is_some_and(|&(_, end)| code_point <= end)
    })
}

#[cfg(test)]
mod tests {
    use super::{STRONG_RTL_RANGES, has_strong_right_to_left};

    #[test]
    fn ascii_neutral_weak_and_other_ltr_text_do_not_match() {
        for text in [
            "",
            "hello",
            "123",
            "+3",
            "https://example.test/path?q=1",
            " \t\n.,!?()[]+-",
            "café Ελληνικά 中文",
            "😀",
            "\u{200e}\u{202b}\u{2067}",
            "\u{301}",
        ] {
            assert!(!has_strong_right_to_left(text), "{text:?}");
        }
    }

    #[test]
    fn all_named_scripts_and_explicit_direction_marks_match() {
        for text in [
            "\u{1e900}", // Adlam
            "\u{627}",   // Arabic
            "\u{5d0}",   // Hebrew
            "\u{840}",   // Mandaic
            "\u{7ca}",   // Nko
            "\u{800}",   // Samaritan
            "\u{710}",   // Syriac
            "\u{780}",   // Thaana
            "\u{200f}",
            "\u{61c}",
            "English first, then עברית",
            "https://example.test/مرحبا",
        ] {
            assert!(has_strong_right_to_left(text), "{text:?}");
        }
    }

    #[test]
    fn script_combining_marks_and_digits_are_not_skipped() {
        for text in [
            "\u{591}",
            "\u{610}",
            "\u{656}",
            "\u{7a6}",
            "\u{660}",
            "\u{6f0}",
            "\u{7c0}",
            "\u{1e950}",
            "Latin \u{591}",
            "123\u{660}",
        ] {
            assert!(has_strong_right_to_left(text), "{text:?}");
        }
        // These nearby characters have Common/Inherited script, not Script=Arabic.
        for text in ["\u{64b}", "\u{651}", "\u{670}", "\u{6dd}", "\u{8e2}"] {
            assert!(!has_strong_right_to_left(text), "{text:?}");
        }
    }

    #[test]
    fn supplementary_ranges_include_their_entire_explicit_intervals() {
        for code_point in [0x10800, 0x10FFF, 0x1E800, 0x1E8FF, 0x1E900, 0x1EFFF] {
            let text = char::from_u32(code_point).unwrap().to_string();
            assert!(has_strong_right_to_left(&text), "U+{code_point:04X}");
        }
        for code_point in [0x107FF, 0x11000, 0x1E7FF, 0x1F000, 0x10FFFF] {
            let text = char::from_u32(code_point).unwrap().to_string();
            assert!(!has_strong_right_to_left(&text), "U+{code_point:04X}");
        }
    }

    #[test]
    fn merged_table_preserves_every_boundary_gap() {
        for (index, &(start, end)) in STRONG_RTL_RANGES.iter().enumerate() {
            assert!(start <= end);
            if index > 0 {
                assert!(STRONG_RTL_RANGES[index - 1].1 + 1 < start);
            }
            for code_point in [start, end] {
                let text = char::from_u32(code_point).unwrap().to_string();
                assert!(has_strong_right_to_left(&text), "U+{code_point:04X}");
            }
            for code_point in [start - 1, end + 1] {
                let text = char::from_u32(code_point).unwrap().to_string();
                assert!(!has_strong_right_to_left(&text), "U+{code_point:04X}");
            }
        }
        // Guard specifically against replacing the source with broad Arabic blocks.
        for text in [
            "\u{605}", "\u{60c}", "\u{61b}", "\u{61f}", "\u{640}", "\u{fd3e}",
        ] {
            assert!(!has_strong_right_to_left(text), "{text:?}");
        }
    }

    #[test]
    fn full_scalar_corpus_matches_original_chrome_expression_fingerprint() {
        // Independently recorded from the original JS regex in the engine above.
        // FNV-1a over one match byte (0 or 1) per scalar, in code-point order;
        // skip surrogate code points, exactly as Rust's char representation does.
        let mut hash = 0x811C_9DC5_u32;
        let mut matching_count = 0;
        let mut scalar_count = 0;
        let mut buffer = [0; 4];
        for character in (0..=0x10FFFF).filter_map(char::from_u32) {
            let is_match = has_strong_right_to_left(character.encode_utf8(&mut buffer));
            hash = (hash ^ u32::from(is_match)).wrapping_mul(0x0100_0193);
            matching_count += usize::from(is_match);
            scalar_count += 1;
        }
        assert_eq!(scalar_count, 1_112_064);
        assert_eq!(matching_count, 5_739);
        assert_eq!(hash, 0x99FC_0102);
    }
}
